-- supabase/migrations/20261102T0817_n1d_catalogos_oficiales.sql
--
-- N1 · PR 2 · Respuesta 5, cambio 2 de Julio (02/11/2026): «ninguna lista de
-- opciones laborales se inventa». Las tablas oficiales que usa el paso 1 de la
-- ficha (Resumen, Contrato y salario, Impuestos), SACADAS DE SU DOCUMENTO
-- OFICIAL (regla 5), no de memoria: cada catálogo, con su organismo, su
-- documento, su enlace y su edición en lab_catalogo_fuente.
--
--   · De la Seguridad Social (Sistema RED, Tablas y formatos comunes): claves de
--     contrato (T-19), grupos de cotización (T-18), países (T-12), ocupación
--     CNO-11 (T-90), discapacidad (T-55 y T-72) y colectivo de trabajador (T-61).
--   · De la AEAT (modelo 145, en el BOE): situación familiar y tramos de
--     discapacidad para el IRPF.
--
-- Se guarda el código oficial, la palabra de la calle (calle) y el texto
-- oficial (oficial), que la pantalla enseña en pequeño. La palabra de la calle
-- está ESCRITA A MANO solo para lo que sale en las pantallas 1 a 3 (los dos
-- tipos de contrato de Foodint, los grupos de cotización, los tres países de
-- Foodint, la situación familiar y la discapacidad del IRPF), para que la apruebe Julio; en lo demás, calle =
-- el texto oficial tal cual, hasta que salga en una pantalla. Lo que la tabla oficial
-- da de baja o deja «para uso futuro», con vigente = false (se lee, no se elige).
--
-- El nivel formativo (SEPE) NO está: su tabla no se ha encontrado publicada
-- (el manual de Contrat@ remite a la ayuda XML del portal). No se inventa: la
-- ficha lo enseña como «Falta».
--
-- SOLO AÑADE: dos tablas nuevas y sus filas. Lectura para quien entra (son
-- tablas públicas); nadie escribe desde la aplicación.
--
-- Vuelta atrás: supabase/vuelta-atras/20261102T0817_n1d_catalogos_oficiales.down.sql

create table if not exists public.lab_catalogo_fuente (
  catalogo     text primary key,
  nombre       text not null,
  organismo    text not null,
  documento    text not null,
  url          text not null,
  version      text not null,
  consultado   date not null
);
comment on table public.lab_catalogo_fuente is 'N1 (02/11/2026). De dónde sale cada catálogo oficial de Laboral: organismo, documento, enlace y edición. Regla: ninguna lista laboral se inventa.';

create table if not exists public.lab_catalogo (
  catalogo    text not null references public.lab_catalogo_fuente(catalogo) on delete cascade,
  codigo      text not null,
  calle       text not null,
  oficial     text not null,
  comentario  text,
  vigente     boolean not null default true,
  orden       integer not null default 0,
  primary key (catalogo, codigo)
);
comment on table public.lab_catalogo is 'N1 (02/11/2026). Las filas de cada catálogo oficial: el código oficial, la palabra de la calle y el texto oficial.';

alter table public.lab_catalogo_fuente enable row level security;
alter table public.lab_catalogo enable row level security;
revoke all on public.lab_catalogo_fuente from anon, authenticated;
revoke all on public.lab_catalogo from anon, authenticated;
grant select on public.lab_catalogo_fuente to authenticated;
grant select on public.lab_catalogo to authenticated;
drop policy if exists lab_catalogo_fuente_read on public.lab_catalogo_fuente;
create policy lab_catalogo_fuente_read on public.lab_catalogo_fuente for select to authenticated using (true);
drop policy if exists lab_catalogo_read on public.lab_catalogo;
create policy lab_catalogo_read on public.lab_catalogo for select to authenticated using (true);

on conflict (catalogo) do update set nombre = excluded.nombre, organismo = excluded.organismo, documento = excluded.documento, url = excluded.url, version = excluded.version, consultado = excluded.consultado;

on conflict (catalogo, codigo) do update set calle = excluded.calle, oficial = excluded.oficial, comentario = excluded.comentario, vigente = excluded.vigente, orden = excluded.orden;
